logger_get_mask_expanded (struct t_gui_buffer *buffer, const char *mask)
{
   char *mask2, *mask_decoded, *mask_decoded2, *mask_decoded3, *mask_decoded4;
   char *mask_decoded5;
    const char *dir_separator;
    int length;
    time_t seconds;
    struct tm *date_tmp;

    mask2 = NULL;
   mask_decoded = NULL;
   mask_decoded2 = NULL;
   mask_decoded3 = NULL;
   mask_decoded4 = NULL;
   mask_decoded5 = NULL;

    dir_separator = weechat_info_get ("dir_separator", "");
    if (!dir_separator)
        return NULL;

    /*
     * we first replace directory separator (commonly '/') by \01 because
     * buffer mask can contain this char, and will be replaced by replacement
     * char ('_' by default)
     */
   mask2 = weechat_string_replace (mask, dir_separator, "\01");
   if (!mask2)
        goto end;

   mask_decoded = weechat_buffer_string_replace_local_var (buffer, mask2);
   if (!mask_decoded)
        goto end;

   mask_decoded2 = weechat_string_replace (mask_decoded,
                                           dir_separator,
                                           weechat_config_string (logger_config_file_replacement_char));
   if (!mask_decoded2)
        goto end;

#ifdef __CYGWIN__
   mask_decoded3 = weechat_string_replace (mask_decoded2, "\\",
                                           weechat_config_string (logger_config_file_replacement_char));
#else
   mask_decoded3 = strdup (mask_decoded2);
#endif /* __CYGWIN__ */
   if (!mask_decoded3)
        goto end;

    /* restore directory separator */
   mask_decoded4 = weechat_string_replace (mask_decoded3,
                                           "\01", dir_separator);
   if (!mask_decoded4)
       goto end;
   /* replace date/time specifiers in mask */
   length = strlen (mask_decoded4) + 256 + 1;
   mask_decoded5 = malloc (length);
   if (!mask_decoded5)
        goto end;
   seconds = time (NULL);
   date_tmp = localtime (&seconds);
   mask_decoded5[0] = '\0';
   strftime (mask_decoded5, length - 1, mask_decoded4, date_tmp);

    /* convert to lower case? */
    if (weechat_config_boolean (logger_config_file_name_lower_case))
       weechat_string_tolower (mask_decoded5);

    if (weechat_logger_plugin->debug)
    {
       weechat_printf_date_tags (NULL, 0, "no_log",
                                 "%s: buffer = \"%s\", mask = \"%s\", "
                                  "decoded mask = \"%s\"",
                                  LOGGER_PLUGIN_NAME,
                                  weechat_buffer_get_string (buffer, "name"),
                                 mask, mask_decoded5);
    }

end:
    if (mask2)
        free (mask2);
   if (mask_decoded)
       free (mask_decoded);
   if (mask_decoded2)
       free (mask_decoded2);
   if (mask_decoded3)
       free (mask_decoded3);
   if (mask_decoded4)
       free (mask_decoded4);
   return mask_decoded5;
}

static ssize_t oz_cdev_write(struct file *filp, const char __user *buf,
		size_t count, loff_t *fpos)
{
	struct oz_pd *pd;
	struct oz_elt_buf *eb;
	struct oz_elt_info *ei;
	struct oz_elt *elt;
 	struct oz_app_hdr *app_hdr;
 	struct oz_serial_ctx *ctx;

 	spin_lock_bh(&g_cdev.lock);
 	pd = g_cdev.active_pd;
 	if (pd)
		oz_pd_get(pd);
	spin_unlock_bh(&g_cdev.lock);
	if (pd == NULL)
		return -ENXIO;
	if (!(pd->state & OZ_PD_S_CONNECTED))
		return -EAGAIN;
	eb = &pd->elt_buff;
	ei = oz_elt_info_alloc(eb);
	if (ei == NULL) {
		count = 0;
		goto out;
	}
	elt = (struct oz_elt *)ei->data;
	app_hdr = (struct oz_app_hdr *)(elt+1);
	elt->length = sizeof(struct oz_app_hdr) + count;
	elt->type = OZ_ELT_APP_DATA;
	ei->app_id = OZ_APPID_SERIAL;
	ei->length = elt->length + sizeof(struct oz_elt);
	app_hdr->app_id = OZ_APPID_SERIAL;
	if (copy_from_user(app_hdr+1, buf, count))
		goto out;
	spin_lock_bh(&pd->app_lock[OZ_APPID_USB-1]);
	ctx = (struct oz_serial_ctx *)pd->app_ctx[OZ_APPID_SERIAL-1];
	if (ctx) {
		app_hdr->elt_seq_num = ctx->tx_seq_num++;
		if (ctx->tx_seq_num == 0)
			ctx->tx_seq_num = 1;
		spin_lock(&eb->lock);
		if (oz_queue_elt_info(eb, 0, 0, ei) == 0)
			ei = NULL;
		spin_unlock(&eb->lock);
	}
	spin_unlock_bh(&pd->app_lock[OZ_APPID_USB-1]);
out:
	if (ei) {
		count = 0;
		spin_lock_bh(&eb->lock);
		oz_elt_info_free(eb, ei);
		spin_unlock_bh(&eb->lock);
	}
	oz_pd_put(pd);
	return count;
}

baseline_explanation:
The code is a function that writes data to a device. It first locks a global spinlock, then retrieves a pointer to a data structure associated with the device. If the device is not connected, it returns an error. It then allocates a new data structure, fills it with data from a user buffer, and queues it for transmission. The function then unlocks the spinlock and returns the number of bytes written. The function is vulnerable to a race condition because it does not check if the device is still connected after acquiring the lock. If the device is disconnected while the lock is held, the function will dereference a null pointer and return an error. This is dangerous because it can lead to a system crash or other undefined behavior.

The exact line or logic that is vulnerable is the following:

```c
if(pd==NULL)return-ENXIO;
if(!(pd->state&OZ_PD_S_CONNECTED))return-EAGAIN;
```

These lines check if the device is connected and if it is, they return an error if it is not. However, there is a race condition because the device could be disconnected between the time these checks are made and the time the function checks if the device is still connected.

The danger of this vulnerability is that it can lead to a system crash or other undefined behavior if the device is disconnected while the lock is held. This is because the function will dereference a null pointer when it tries to access the device data structure.

To fix this vulnerability, the function should check if the device is still connected after acquiring the lock. This can be done by moving the check inside the critical section, like so:

```c
spin_lock_bh(&g_cdev.lock);
pd = g_cdev.active_pd;
if (pd) {
    oz_pd_get(pd);
}
spin_unlock_bh(&g_cdev.lock);

if (pd == NULL) {
    return -ENXIO;
}

if (!(pd->state & OZ_PD_S_CONNECTED)) {
    oz_pd_put(pd);
    return -EAGAIN;
}
```

This way, the function will not dereference a null pointer and will return an error if the device is disconnected while the lock is held.

truth_description:
Vulnerability Type: CWE-416
Context: fork: fix incorrect fput of ->exe_file causing use-after-free

Commit 7c051267931a ("mm, fork: make dup_mmap wait for mmap_sem for
write killable") made it possible to kill a forking task while it is
waiting to acquire its ->mmap_sem for write, in dup_mmap().

However, it was overlooked that this introduced an new error path before
a reference is taken on the mm_struct's ->exe_file.  Since the
->exe_file of the new mm_struct was already set to the old ->exe_file by
the memcpy() in dup_mm(), it was possible for the mmput() in the error
path of dup_mm() to drop a reference to ->exe_file which was never
taken.

This caused the struct file to later be freed prematurely.

Fix it by updating mm_init() to NULL out the ->exe_file, in the same
place it clears other things like the list of mmaps.

This bug was found by syzkaller.  It can be reproduced using the
following C program:

    #define _GNU_SOURCE
    #include <pthread.h>
    #include <stdlib.h>
    #include <sys/mman.h>
    #include <sys/syscall.h>
    #include <sys/wait.h>
    #include <unistd.h>

    static void *mmap_thread(void *_arg)
    {
        for (;;) {
            mmap(NULL, 0x1000000, PROT_READ,
                 MAP_POPULATE|MAP_ANONYMOUS|MAP_PRIVATE, -1, 0);
        }
    }

    static void *fork_thread(void *_arg)
    {
        usleep(rand() % 10000);
        fork();
    }

    int main(void)
    {
        fork();
        fork();
        fork();
        for (;;) {
            if (fork() == 0) {
                pthread_t t;

                pthread_create(&t, NULL, mmap_thread, NULL);
                pthread_create(&t, NULL, fork_thread, NULL);
                usleep(rand() % 10000);
                syscall(__NR_exit_group, 0);
            }
            wait(NULL);
        }
    }

No special kernel config options are needed.  It usually causes a NULL
pointer dereference in __remove_shared_vm_struct() during exit, or in
dup_mmap() (which is usually inlined into copy_process()) during fork.
Both are due to a vm_area_struct's ->vm_file being used after it's
already been freed.

Google Bug Id: 64772007

Link: http://lkml.kernel.org/r/20170823211408.31198-1-ebiggers3@gmail.com
Fixes: 7c051267931a ("mm, fork: make dup_mmap wait for mmap_sem for write killable")
Signed-off-by: Eric Biggers <ebiggers@google.com>
Tested-by: Mark Rutland <mark.rutland@arm.com>
Acked-by: Michal Hocko <mhocko@suse.com>
Cc: Dmitry Vyukov <dvyukov@google.com>
Cc: Ingo Molnar <mingo@kernel.org>
